import 'dart:io';
import 'package:shelf/shelf.dart';
import 'package:shelf_letsencrypt/shelf_letsencrypt.dart';

void main(List<String> args) async {
  final domains = Domain.fromDomainsNamesAndEmailsArgs('www.domain.com', 'info@domain.com');
  final certificatesHandler = CertificatesHandlerIO(Directory('/var/lib/myapp/certs'));
  final letsEncrypt = LetsEncrypt(certificatesHandler, production: false);
  final pipeline = const Pipeline().addMiddleware(logRequests());
  final handler = pipeline.addHandler((request) => Response.ok('OK'));
  await letsEncrypt.startServer(handler, domains, loadAllHandledDomains: true);
}
